"""Amendment 5: pre-registered tests on RE3 of three hypotheses generated by the
exploratory RE2 analyses (PROTOCOL_V3_AMENDMENT_5.md).

H5a  Baseline-aware log alarms raise the deployed model's AC@1, and by more than
     they raise the detector count (difference in differences > 0).
H5b  Hiding every spelling of every service name (anon_full) does not lower the
     deployed model's AC@1 by more than 0.05 (non-inferiority).
H5c  With the onset placed 120 s late, N-Sigma (H5c-1) and the SimpleRCA-style
     heuristic (H5c-2) lose more AC@1 than the deployed model does
     (difference in differences > 0).

usage: python scripts/15_amendment5.py --ctx out/re3 [--pilot out/pilot_re3.txt]
writes out/re3/amendment5.md and amendment5.json
"""
import argparse
import glob
import importlib.util
import json
import os
import sys

HERE = os.path.dirname(os.path.abspath(__file__))
sys.path.insert(0, os.path.join(HERE, ".."))
from rcastudy import config as C  # noqa: E402

spec = importlib.util.spec_from_file_location("ev", os.path.join(HERE, "06_evaluate.py"))
EV = importlib.util.module_from_spec(spec)
spec.loader.exec_module(EV)

DEP = C.DEPLOYED_MODEL
MODELS = sorted(C.MODELS)
NI = 0.05


def load(ctx):
    cases = EV.load_jsonl(os.path.join(ctx, "contexts.jsonl"))
    meth = {}
    for f in ("ranks_nonllm.json", "ranks_classifiers.json", "ranks_rcaeval.json", "ranks_simplerca_variants.json"):
        p = os.path.join(ctx, f)
        if os.path.exists(p):
            meth.update(json.load(open(p)))
    for p in glob.glob(os.path.join(ctx, "llm", "main__*.jsonl")):
        name = os.path.basename(p)[:-6].split("__", 1)[1]
        meth[f"llm:{name}"] = {k: v["ranking"] for k, v in EV.load_llm(p).items()}
    return cases, meth


def fmt(d, lo, hi):
    return f"{d:+.3f} [{lo:+.3f}, {hi:+.3f}]"


def did(cases, a0, a1, b0, b1):
    """Per-case difference in differences: (a0 - a1) - (b0 - b1), on 0/1 top-1.
    Positive = method a changes more than method b between conditions 0 and 1."""
    vals = {c["case_id"]: (a0[c["case_id"]] - a1[c["case_id"]]) - (b0[c["case_id"]] - b1[c["case_id"]]) for c in cases}
    lo, hi = EV.boot_ci(cases, vals)
    d = sum(vals.values()) / len(vals)
    return {"diff": d, "ci": [lo, hi], "p_perm": EV.perm_p(cases, vals), "n": len(vals)}


def run(cases, ctx, L, label):
    out = {}
    base = load(ctx)[1]
    t = lambda m, rk: EV.top1(cases, rk.get(m, {}))  # noqa: E731
    # ---- H5a
    chronic = f"{ctx}_chronic"
    if os.path.exists(os.path.join(chronic, "contexts.jsonl")):
        cc, cm = load(chronic)
        ccf = {c["case_id"]: c for c in cc}
        cs_new = [ccf[c["case_id"]] for c in cases]
        dep0, dep1 = t(f"llm:{DEP}__annotated", base), EV.top1(cs_new, cm.get(f"llm:{DEP}__annotated", {}))
        det0, det1 = t("detector_count", base), EV.top1(cs_new, cm.get("detector_count", {}))
        r = EV.paired(cases, dep1, dep0)
        dd = did(cases, dep1, dep0, det1, det0)
        out["H5a_model"] = r
        out["H5a_did"] = dd
        L.append(f"- **H5a** flagged cases with the filter: {sum(c['flagged'] for c in cs_new)}/{len(cases)} "
                 f"(without: {sum(c['flagged'] for c in cases)}). Deployed AC@1 {r['b']/r['n']:.3f} -> {r['a']/r['n']:.3f}: "
                 f"{fmt(r['diff'], *r['ci'])}, p {r['p_perm']:.4f}. Detector count "
                 f"{sum(det0.values())/len(det0):.3f} -> {sum(det1.values())/len(det1):.3f}. "
                 f"Difference in differences {fmt(dd['diff'], *dd['ci'])}, p {dd['p_perm']:.4f}.")
    else:
        L.append("- H5a: chronic build not found.")
    # ---- H5b
    for m in MODELS:
        A_, F_ = base.get(f"llm:{m}__annotated", {}), base.get(f"llm:{m}__anon_full", {})
        if not F_:
            continue
        r = EV.paired(cases, EV.top1(cases, F_), EV.top1(cases, A_))
        verdict = "supported" if r["ci"][0] > -NI else "not supported"
        out[f"H5b_{m}"] = dict(r, verdict=verdict)
        tag = "**H5b**" if m == DEP else "H5b (descriptive)"
        L.append(f"- {tag} {m}: anon_full minus annotated {fmt(r['diff'], *r['ci'])}, p {r['p_perm']:.4f}; "
                 f"lower bound > -{NI}: {verdict}.")
    # ---- H5c
    late = f"{ctx}_shift120"
    if os.path.exists(os.path.join(late, "contexts.jsonl")):
        lc, lm = load(late)
        lcf = {c["case_id"]: c for c in lc}
        cs_late = [lcf[c["case_id"]] for c in cases]
        dep0, dep1 = t(f"llm:{DEP}__annotated", base), EV.top1(cs_late, lm.get(f"llm:{DEP}__annotated", {}))
        for key, comp in (("H5c-1", "rcaeval:nsigma"), ("H5c-2", "simplerca")):
            if comp not in lm:
                L.append(f"- {key}: {comp} missing at +120 s.")
                continue
            c0, c1 = t(comp, base), EV.top1(cs_late, lm[comp])
            dd = did(cases, c0, c1, dep0, dep1)
            out[key] = dd
            L.append(f"- **{key}** {comp}: AC@1 {sum(c0.values())/len(c0):.3f} -> {sum(c1.values())/len(c1):.3f}; "
                     f"deployed {sum(dep0.values())/len(dep0):.3f} -> {sum(dep1.values())/len(dep1):.3f}. "
                     f"Loss of {comp} minus loss of the model {fmt(dd['diff'], *dd['ci'])}, p {dd['p_perm']:.4f}.")
    else:
        L.append("- H5c: +120 s build not found.")
    # ---- Holm over the directional tests H5a (did), H5c-1, H5c-2
    fam = [k for k in ("H5a_did", "H5c-1", "H5c-2") if k in out]
    for k, h in zip(fam, EV.holm([out[k]["p_perm"] for k in fam])):
        sup = h < 0.05 and out[k]["diff"] > 0
        out[k]["p_holm"], out[k]["verdict"] = h, ("supported" if sup else "not supported")
        L.append(f"  - {k}: Holm p {h:.4f} -> **{out[k]['verdict']}** (predicted direction: positive)")
    return out


def onset_table(cases, ctx, L):
    """Descriptive: AC@1 at -120, 0, +120 s for the methods of Amendment 4."""
    rows = [f"llm:{DEP}__annotated", "detector_count", "lr_visible", "simplerca", "simplerca:V3",
            "rcaeval:nsigma", "rcaeval:baro"]
    data = {0: load(ctx)}
    for s in (-120, 120):
        p = f"{ctx}_shift{s}"
        if os.path.exists(os.path.join(p, "contexts.jsonl")):
            data[s] = load(p)
    L.append("\n| method | -120 s | 0 s | +120 s |\n|---|---|---|---|")
    for m in rows:
        cells = []
        for s in (-120, 0, 120):
            if s in data and m in data[s][1]:
                cf = {c["case_id"]: c for c in data[s][0]}
                tt = EV.top1([cf[c["case_id"]] for c in cases], data[s][1][m])
                cells.append(f"{sum(tt.values())/len(tt):.3f}")
            else:
                cells.append("-")
        L.append(f"| {m} | " + " | ".join(cells) + " |")


def main():
    ap = argparse.ArgumentParser()
    ap.add_argument("--ctx", required=True)
    ap.add_argument("--pilot", default=None)
    a = ap.parse_args()
    cases = load(a.ctx)[0]
    L = ["# Amendment 5: pre-registered tests on RE3 (15_amendment5.py)\n",
         f"## Primary: all {len(cases)} RE3 cases\n"]
    res = {"all": run(cases, a.ctx, L, "all")}
    if a.pilot and os.path.exists(a.pilot):
        pilot = {l.strip() for l in open(a.pilot) if l.strip()}
        sub = [c for c in cases if c["case_id"] not in pilot]
        L.append(f"\n## Sensitivity: {len(sub)} cases outside the pilot\n")
        res["no_pilot"] = run(sub, a.ctx, L, "no_pilot")
    L.append("\n## Descriptive: onset shifts on RE3")
    onset_table(cases, a.ctx, L)
    with open(os.path.join(a.ctx, "amendment5.md"), "w") as f:
        f.write("\n".join(L) + "\n")
    with open(os.path.join(a.ctx, "amendment5.json"), "w") as f:
        json.dump(res, f, indent=1, default=float)
    print("\n".join(L))


if __name__ == "__main__":
    main()
